const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function revenueEvidenceHtml(observation, label='revenue') {
 if(!observation)return '';
 const o=observation;
 return `<section><h3>Base ${escape(label)} evidence</h3><p>Passage and printed number matched; period, currency and accounting meaning confirmed by the analyst, not independently verified.</p><p>${escape(o.token)} ${escape(o.unit)} ${escape(o.currency)} = ${escape(o.valueMillions)} million · FY${escape(o.fiscalYear)}.</p><p>${escape(o.filename)} · ${escape(o.locator)} · ${escape(o.basis)}</p><blockquote>${escape(o.excerpt)}</blockquote><p>Research run: ${escape(o.researchRunId)}<br>Observed source URL: ${escape(o.sourceUrl||'Not recorded')}<br>Original SHA-256: ${escape(o.originalHash)}<br>Extracted text SHA-256: ${escape(o.extractionHash)}</p><p>This historical receipt describes evidence at the saved revision; current availability and permissions may differ.</p></section>`;
}
export function ebitdaReconciliationHtml(bridge) {
 if(!bridge)return '';
 return `<section><h3>Reported-to-adjusted EBITDA reconciliation</h3><p>Arithmetic checked; accounting treatment, sources and recurrence remain analyst judgments. All amounts in the model currency and millions, for its base fiscal year.</p><p>Starting EBITDA: ${escape(bridge.startingEbitda)} · ${escape(bridge.startingBasis)}<br>Source: ${escape(bridge.sourceReference)}</p><ul>${bridge.adjustments.map(r=>`<li>${escape(r.label)}: ${escape(r.amount)} (${escape(r.recurrence)}) · ${escape(r.reference)}</li>`).join('')}</ul><p>Signed adjustments: ${escape(bridge.totalAdjustments)}. Reconciled base EBITDA: ${escape(bridge.reconciledEbitda)}.</p></section>`;
}
export function operatingModelHtml(model) {
 if(!model?.results)return '';
 const fields={growthPct:'Revenue CAGR (%)',marginPct:'Target EBITDA margin (%)',multiple:'EV/EBITDA',netDebt:'Target net debt (m)',otherClaims:'Other senior claims (m)',nonOperatingAssets:'Nonoperating assets (m)',shares:'Target diluted shares (m)'};
 return `<section><h2>Operating scenarios · ${escape(model.version)}</h2><p>Analyst-entered inputs; manual references are unverified. Conditional outcomes, not forecasts. Currency: ${escape(model.currency)}. All money and shares in millions except share prices.</p><p>Base FY${escape(model.baseYear)} revenue: ${escape(model.baseRevenue)} million. Target FY${escape(model.targetYear)}. Reference share price: ${escape(model.referencePrice)} as of ${escape(model.asOf)}.</p><p>Revenue source: ${escape(model.revenueReference)}<br>Price source: ${escape(model.priceReference)}<br>EBITDA basis: ${escape(model.ebitdaBasis)}</p>${['Cash','Debt'].map(k=>model['base'+k]!==undefined?`<p>Year-end ${k}: ${escape(model['base'+k])} million; ${escape(model['base'+k+'Basis'])}. Source: ${escape(model['base'+k+'Reference'])}.</p>${revenueEvidenceHtml(model['base'+k+'Observation'],k)}`:'').join('')}${model.historicalNetDebt!==undefined?`<p>Historical net debt: ${escape(model.historicalNetDebt)} million. Target-period scenario debt remains separate.</p>`:''}${ebitdaReconciliationHtml(model.ebitdaReconciliation)}${revenueEvidenceHtml(model.baseRevenueObservation)}${revenueEvidenceHtml(model.baseEbitdaObservation,'EBITDA')}${model.baseEbitda?`<p>Historical EBITDA: ${escape(model.baseEbitda)} million; margin ${escape(model.baseMarginPct)}%. Source: ${escape(model.baseEbitdaReference)}. Historical/forecast definitions confirmed comparable by analyst.</p>`:''}<p>Revenue = base revenue × (1 + CAGR) ^ year interval. EBITDA = revenue × margin. EV = EBITDA × multiple. Equity = max(0, EV − net debt − other claims + nonoperating assets). Price = equity ÷ diluted shares.</p>${['bear','base','bull'].map(n=>`<article><h3>${n}</h3><p>${Object.entries(fields).map(([k,label])=>`${label}: ${escape(model.scenarios[n][k])}`).join('<br>')}</p>${model.baseEbitda?`<p>Margin change: ${escape(model.results[n].marginChangePp)} percentage points; total EBITDA growth: ${escape(model.results[n].ebitdaGrowthPct)}%.</p>`:''}<p>Rationale / references: ${escape(model.scenarios[n].rationale)}</p><p>Computed revenue: ${escape(model.results[n].revenue)}m; EBITDA: ${escape(model.results[n].ebitda)}m; EV: ${escape(model.results[n].enterpriseValue)}m; equity: ${escape(model.results[n].equityValue)}m.<br>Implied share price: ${escape(model.results[n].impliedPrice)} ${escape(model.currency)}; price return: ${escape(model.results[n].priceReturnPct)}%.</p></article>`).join('')}<p>${(model.warnings||[]).map(escape).join('<br>')}</p></section>`;
}
