const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function committeeDocument(run){
 return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Committee review</title><style>body{font-family:Calibri,sans-serif;color:black;max-width:900px;margin:auto;padding:24px}article{border-top:1px solid #bbb;padding:16px 0}p,blockquote{white-space:pre-wrap;overflow-wrap:anywhere}</style></head><body><h1>${esc(run.ticker)} · Draft investment committee</h1><p>Run ${esc(run.id)} · ${esc(run.status)} · case R${esc(run.baseline.revision)} · model ${esc(run.model)}. Five roles, same model; not independent human reviewers. No investor approval or case changes.</p>${(run.state?.sections||[]).map(s=>`<article><h2>${esc(s.title)}</h2>${s.claims.map(c=>`<p>${esc(c.id)} · ${esc(c.basis)} · ${esc(c.review)}</p><p>${esc(c.statement)}</p><p>${esc(c.reviewReason)}</p>${c.evidence.map(e=>`<blockquote>${esc(e.sourceId)} · ${e.matched?'passage matched':'unmatched'}: ${esc(e.excerpt)}</blockquote>`).join('')}`).join('')}<p>Gaps: ${s.gaps.map(esc).join('; ')}</p></article>`).join('')}<h2>Named challenges and unaccepted responses</h2>${(run.state?.challenges||[]).map(c=>{const r=run.state?.responses?.find(r=>r.challengeId===c.id);return `<article><h3>${esc(c.question)}</h3><p>Assessments: ${c.claimIds.map(esc).join(', ')}</p><p>${esc(r?.status||'pending')}: ${esc(r?.reason)}</p><p>Next test: ${esc(r?.nextTest)}</p><p>Unaccepted proposal: ${esc(r?.proposedChange)}</p></article>`;}).join('')}<h2>Frozen sources</h2>${(run.sources||[]).map(s=>`<p>${esc(s.id)} · ${esc(s.filename)} · ${esc(s.sourceUrl)}<br>Original: ${esc(s.originalHash)}<br>Extraction: ${esc(s.extractionHash)}</p>`).join('')}<p>Source-pack coverage only. Passage matching and model review do not establish truth. Initial dissent remains preserved; lead responses are unverified proposals.</p></body></html>`;
}
